/*
 * dir_$old_read_entries - read entries of an old-format directory into a
 * caller's buffer
 *
 * Original address: 0x00E579C0
 * Size: 704 bytes (0x00E579C0 .. 0x00E57C7F)
 * Generated by: Claude Opus 5.5
 *
 * Module-local routine of the OLD_DIR segment (no map symbol); its one
 * caller is DIR_$OLD_DIR_READU (0x00E57CCE), which dereferences its third
 * and fourth arguments into max_entries and buf_size.
 *
 * Frame: (0x8,A6) uid, (0xC,A6) cursor (two words {sub, index}: sub 0 =
 * inline slot `index', else slot `sub' of block `index'), (0x10,A6)
 * max_entries, (0x14,A6) buf_size in bytes, (0x18,A6) buf, (0x1C,A6)
 * count_ret (A3), (0x20,A6) status_ret.  Locals: A6-0x34 the handle,
 * A6-0x30 the buffer words used, A6-0x28 the unmapped name, A6-0x36 its
 * length, A6-0x56 the stored length as a word, A6-0x40 the truncation
 * flag.  D5 = sub, D4 = index.
 *
 * Blocks:
 *   0x00E579C8-0x00E579E6  *count_ret = 0, used = 0; max_entries 0 or a
 *                          zero cursor longword: *status_ret = ok and
 *                          return at once (no ACL_$EXIT_SUPER)
 *   0x00E579EA-0x00E57A0A  NAME_$LOCK_DIR(uid, &handle, 1, 4, status_ret);
 *                          error -> ACL_$EXIT_SUPER
 *   0x00E57A0E-0x00E57A34  sub == 0 and index above the inline slot count:
 *                          status_$naming_illegal_directory_operation, to
 *                          the unlock
 *   0x00E57A38-0x00E57B26  inline phase: a used slot (type != 0) is
 *                          emitted (below); then stop with cursor {0,0} when
 *                          *count_ret reaches the header's +0x16 count;
 *                          step index, past the inline slots go to {1,1};
 *                          stop when *count_ret == max_entries
 *   0x00E57B30-0x00E57C4A  block phase: index above blocks used (+0xA) ->
 *                          {0,0}, stop; a block with no slots in use ->
 *                          {1, index+1}; a used slot is emitted; stop with
 *                          {0,0} when *count_ret reaches the header's +0x18
 *                          word; step sub, past the block's slots go to
 *                          {1, index+1}; stop when *count_ret == max_entries
 *   emit (0x00E57A58-0x00E57AFE, again at 0x00E57B78-0x00E57C1E):
 *                          UNMAP_CASE(name, &len, tmp, &0x20, &n, &trunc);
 *                          size = (0x1A + n) & ~3; if used*2 + size >
 *                          buf_size (unsigned) stop, the cursor left on
 *                          this entry; else ++*count_ret, the record at
 *                          buf + used*2 gets size, type, UID, extra, the
 *                          entry's own cursor, n and the name plus a NUL;
 *                          used += size/2
 *   0x00E57C4E-0x00E57C6E  NAME_$UNLOCK_DIR(status_ret); ok -> store the
 *                          cursor, *status_ret = ok
 *   0x00E57C70             ACL_$EXIT_SUPER
 *
 * Quirks reproduced:
 *   - NAME_$UNLOCK_DIR writes status_ret, so the illegal-operation status
 *     set at 0x00E57A2E survives only if the unlock itself fails.
 *   - The inline phase stops at the +0x16 entry count, the block phase at
 *     the +0x18 word.
 *   - The early exit skips ACL_$EXIT_SUPER, every other exit runs it.
 *   - The two emit blocks are the same code in the image; here they are
 *     one static helper taking the slot's field addresses.
 */

#include "dir/dir_internal.h"

/* `move.l #0x10004,-(SP)' 0x00E579EE: NAME_$LOCK_DIR mode 1, rights 4 */
#define OLD_READ_LOCK_MODE      1
#define OLD_READ_LOCK_RIGHTS    4
/* `moveq #0x1a,D1' / `andi.w #-0x4,D1w': record header plus NUL, rounded */
#define OLD_READ_REC_BASE       0x1A

/*
 * Emit one entry.  Returns FALSE when the record does not fit (the image
 * branches to the unlock at 0x00E57C4E).
 */
static int8_t dir_$old_read_emit(dir_$old_slot_t *slot, uint16_t *cursor,
                                 uint16_t sub, uint16_t index,
                                 uint32_t buf_size, uint8_t *buf,
                                 uint32_t *used, uint32_t *count_ret)
{
    char tmp[0x20];                     /* A6-0x28 */
    int16_t n;                          /* A6-0x36 -> D3 */
    int16_t len_w;                      /* A6-0x56 */
    uint8_t trunc[2];                   /* A6-0x40 */
    uint16_t size;                      /* D1 */
    dir_$old_readu_rec_t *rec;          /* A0 */
    int16_t k;
    int16_t i;

    len_w = slot->name_len;
    UNMAP_CASE((char *)slot->name, &len_w, tmp,
               (int16_t *)&name_$leaf_max_len_00e544ae, &n, trunc);
    size = (uint16_t)((OLD_READ_REC_BASE + n) & ~3);
    if ((uint32_t)size + *used * 2 > buf_size) {
        return 0;
    }

    (*count_ret)++;
    rec = (dir_$old_readu_rec_t *)(buf + *used * 2);
    *used += (uint32_t)size >> 1;
    rec->size = size;
    cursor[1] = index;
    cursor[0] = sub;
    rec->cursor[0] = cursor[0];
    rec->cursor[1] = cursor[1];
    k = (int16_t)(n - 1);
    if (k >= 0) {
        i = 1;
        do {                            /* dbf D1w */
            rec->name[i - 1] = (uint8_t)tmp[i - 1];
            i++;
        } while (k-- != 0);
    }
    rec->name[n] = 0;
    rec->name_len = (uint16_t)n;
    rec->type = slot->type;
    rec->uid.high = slot->uid.high;
    rec->uid.low = slot->uid.low;
    rec->extra = slot->extra;
    return (int8_t)0xFF;
}

void dir_$old_read_entries(uid_t *uid, uint16_t *cursor, uint32_t max_entries,
                           uint32_t buf_size, uint8_t *buf,
                           uint32_t *count_ret, status_$t *status_ret)
{
    uint32_t handle;                    /* A6-0x34 */
    uint8_t *dir;
    uint32_t used;                      /* A6-0x30 */
    uint16_t sub;                       /* D5 */
    uint16_t index;                     /* D4 */
    dir_$old_slot_t *slot;              /* A2 */
    uint8_t *block;                     /* A0 */

    /* 0x00E579C8-0x00E579E6 */
    *count_ret = 0;
    used = 0;
    if (max_entries == 0 || (cursor[0] == 0 && cursor[1] == 0)) {
        *status_ret = status_$ok;
        return;
    }

    /* 0x00E579EA-0x00E57A0A */
    NAME_$LOCK_DIR(uid, &handle, OLD_READ_LOCK_MODE, OLD_READ_LOCK_RIGHTS,
                   status_ret);
    if (*status_ret != status_$ok) {
        goto exit_super;
    }
    dir = (uint8_t *)ARCH_VA_TO_PTR(handle);

    sub = cursor[0];
    index = cursor[1];

    if (sub == 0) {
        /* 0x00E57A1E-0x00E57A34 */
        if (index > DIR_OLD_W(dir, DIR_OLD_HDR_INLINE_SLOTS)) {
            *status_ret = status_$naming_illegal_directory_operation;
            goto unlock;
        }

        /* 0x00E57A38-0x00E57B2C */
        while (sub == 0) {
            slot = (dir_$old_slot_t *)(dir + DIR_OLD_SLOT_STRIDE * (uint32_t)index -
                                       DIR_OLD_INLINE_SLOT_BIAS);
            if (slot->type != 0) {
                if (dir_$old_read_emit(slot, cursor, sub, index, buf_size,
                                       buf, &used, count_ret) >= 0) {
                    goto unlock;
                }
            }
            /* 0x00E57B04-0x00E57B26 */
            if ((uint32_t)DIR_OLD_W(dir, DIR_OLD_HDR_ENTRIES) <= *count_ret) {
                index = 0;
                sub = 0;
                goto unlock;
            }
            index++;
            if (index > DIR_OLD_W(dir, DIR_OLD_HDR_INLINE_SLOTS)) {
                index = 1;
                sub = 1;
            }
            if (max_entries == *count_ret) {
                goto unlock;
            }
        }
    }

    /* 0x00E57B30-0x00E57C4A */
    for (;;) {
        if (index > DIR_OLD_W(dir, DIR_OLD_HDR_BLOCKS)) {
            sub = 0;
            index = 0;
            goto unlock;
        }
        block = DIR_OLD_BLOCK(dir, index);
        if (block[DIR_OLD_BLOCK_USED] == 0) {
            sub = 1;
            index++;
            continue;
        }
        slot = DIR_OLD_BLOCK_SLOT(dir, index, sub);
        if (slot->type != 0) {
            if (dir_$old_read_emit(slot, cursor, sub, index, buf_size, buf,
                                   &used, count_ret) >= 0) {
                goto unlock;
            }
        }
        /* 0x00E57C24-0x00E57C4A */
        if ((uint32_t)DIR_OLD_W(dir, DIR_OLD_HDR_ENTRIES_18) <= *count_ret) {
            index = 0;
            sub = 0;
            goto unlock;
        }
        sub++;
        if (sub > DIR_OLD_W(dir, DIR_OLD_HDR_BLOCK_SLOTS)) {
            sub = 1;
            index++;
        }
        if (max_entries == *count_ret) {
            goto unlock;
        }
    }

unlock:
    /* 0x00E57C4E-0x00E57C6E */
    NAME_$UNLOCK_DIR(status_ret);
    if (*status_ret == status_$ok) {
        cursor[0] = sub;
        cursor[1] = index;
        *status_ret = status_$ok;
    }

exit_super:
    /* 0x00E57C70 */
    ACL_$EXIT_SUPER();
}
